            const url = URL.createObjectURL(blob)
            const link = document.createElement('a')
            link.href = url
            const safeName = String(meta.name || '').replace(/[\\/:*?"<>|]/g, '_')
            link.download = safeName + '_' + meta.version + '_' + meta.v + '_' + timestamp + '.txt'
            link.click()
